ini_set('session.use_strict_mode','1');session_set_cookie_params(['secure'=>true,'httponly'=>true,'samesite'=>'Lax']);session_start();
header('Cache-Control: no-store');header('Referrer-Policy: no-referrer');header('X-Content-Type-Options: nosniff');header('X-Robots-Tag: noindex, nofollow');header("Content-Security-Policy: default-src 'self'; style-src 'self' 'unsafe-inline'; script-src 'self' 'unsafe-inline'; img-src 'self' data:; media-src 'self' blob:; frame-ancestors 'none'; base-uri 'none'");
require __DIR__.'/operations-bootstrap.php';
function portalEsc($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function portalJson($v,$status=200){http_response_code($status);header('Content-Type: application/json; charset=utf-8');echo opsJson($v);exit;}
$token=$_GET['token']??'';$link=preg_match('/^[a-f0-9]{64}$/D',$token)?opsOne($pdo,'SELECT * FROM ops_links WHERE token=? AND active=1',[$token]):null;
if(!$link){http_response_code(404);exit('Ссылка недействительна или закрыта владельцем.');}$uid=(int)$link['user_id'];$biz=opsOne($pdo,'SELECT biz_name FROM users WHERE id=?',[$uid]);$_SESSION['portal_csrf']??=bin2hex(random_bytes(32));$passport=null;
if($link['kind']==='passport')try{$passport=opsGetRecord($pdo,$uid,(int)$link['target_id'],'ops_passport')['data'];}catch(Throwable $e){http_response_code(404);exit('Карточка закрыта.');}
if(isset($_GET['image'])){$image=$_GET['image'];$allowed=false;foreach($passport['events']??[] as $event)if(!empty($event['public'])&&in_array($image,$event['photos']??[],true))$allowed=true;if(!$allowed||!preg_match('/^[a-f0-9]{48}$/D',$image)){http_response_code(404);exit;}$file=dirname(__DIR__).'/aulieata-media/'.$image.'.jpg';if(!is_file($file)){http_response_code(404);exit;}header('Content-Type: image/jpeg');header('Content-Disposition: inline');readfile($file);exit;}
if($_SERVER['REQUEST_METHOD']==='POST')try{
    if($link['kind']!=='feedback')throw new RuntimeException('Форма недоступна');$d=json_decode(file_get_contents('php://input'),true);if(!is_array($d)||!hash_equals($_SESSION['portal_csrf'],$d['csrf']??''))portalJson(['error'=>'Обновите страницу'],403);if(!empty($d['website']))throw new RuntimeException('Не удалось отправить форму');$bucket='feedback:'.$uid.':'.hash('sha256',($_SERVER['REMOTE_ADDR']??'').$runtimeConfig['webhook_secret']);opsRateLimit($pdo,$bucket,12,3600);
    if(($d['action']??'')==='transcribe')portalJson(['text'=>opsTranscribe($runtimeConfig,$d['audio']??'')]);$text=opsText($d['text']??'',6000);if(!$text)throw new RuntimeException('Напишите отзыв или запишите голосовое сообщение');$category='Другое';$summary=$text;try{$analysis=opsAI($runtimeConfig,'Разбери обратную связь клиента. JSON {"category":"Обслуживание|Ожидание|Качество|Ошибка заказа|Предложение|Другое","summary":"кратко и нейтрально"}. Не делай выводов о виновности сотрудников или правдивости клиента.',$text);$category=opsText($analysis['category']??'Другое',80);$summary=opsText($analysis['summary']??$text,1500);}catch(Throwable $ignored){}
    $id=opsTicket($pdo,$uid,['name'=>'Обратная связь посетителя','channel'=>'qr','text'=>$text,'summary'=>$summary,'category'=>$category,'contact'=>opsText($d['contact']??'',150)]);portalJson(['ok'=>true,'number'=>$id]);
}catch(Throwable $e){portalJson(['error'=>$e instanceof PDOException?'Не удалось отправить. Повторите позже.':$e->getMessage()],422);}
?><!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=portalEsc($biz['biz_name']??'AulieAta')?></title><style>body{background:#f5f4ee;color:#123025;font:16px system-ui;margin:0;padding:28px 16px}main{max-width:720px;margin:auto}section{background:white;border:1px solid #e0e6db;border-radius:20px;padding:24px;margin:18px 0}h1{font-size:30px}p{line-height:1.65;white-space:pre-wrap}label{display:block;margin:16px 0 6px}input,textarea,button{box-sizing:border-box;font:inherit;padding:13px;border:1px solid #cdd8ca;border-radius:10px}input,textarea{width:100%}textarea{min-height:160px}button{cursor:pointer;background:#123025;color:white;margin:10px 8px 0 0}button:disabled{opacity:.5}.muted{color:#6b7c70}.badge{display:inline-block;background:#d1f58a;padding:7px 12px;border-radius:20px}.event{border-left:3px solid #bde677;padding-left:18px;margin:25px 0}.event img{max-width:100%;border-radius:12px;margin:8px 0}.error{color:#a02924}</style><main><p class="muted"><?=portalEsc($biz['biz_name']??'Бизнес')?></p>
<?php if($passport):?><h1><?=portalEsc($passport['name'])?></h1><span class="badge"><?=portalEsc($passport['status'])?></span><section><p><?=portalEsc($passport['public_summary'])?></p><?php if($passport['terms']):?><h2>Условия обслуживания</h2><p><?=portalEsc($passport['terms'])?></p><?php endif;?></section><section><h2>История</h2><?php foreach($passport['events'] as $e):if(empty($e['public']))continue;?><div class="event"><small class="muted"><?=portalEsc($e['at'])?></small><p><?=portalEsc($e['text'])?></p><?php foreach($e['photos']??[] as $photo):?><img alt="Фото обслуживания" loading="lazy" src="?token=<?=portalEsc($token)?>&amp;image=<?=portalEsc($photo)?>"><?php endforeach;?></div><?php endforeach;?></section><p class="muted">Это персональная ссылка. Передавайте её только тем, кому хотите показать историю.</p>
<?php else:?><h1><?=portalEsc(opsSettings($pdo,$uid)['feedback_title'])?></h1><p>Сообщение попадёт сотрудникам заведения. Можно написать на русском, қазақша или записать голосом.</p><section><form id="feedback"><label for="text">Ваше сообщение</label><textarea id="text" required maxlength="6000"></textarea><button type="button" id="voice">Записать голосом</button><p class="muted">Голос будет передан Google Gemini для расшифровки. Перед отправкой вы сможете исправить текст.</p><label for="contact">Как с вами связаться — по желанию</label><input id="contact" maxlength="150" placeholder="Телефон или другой контакт"><input id="website" tabindex="-1" autocomplete="off" aria-hidden="true" style="display:none"><button id="send">Отправить сотруднику</button><p id="result" role="status"></p></form></section><script>
const csrf=<?=json_encode($_SESSION['portal_csrf'])?>;let recorder,stream,chunks=[],timer;const status=document.getElementById('result');async function call(d){const r=await fetch(location.href,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...d,csrf})});const j=await r.json();if(!r.ok||j.error)throw Error(j.error||'Не удалось отправить');return j}function fileData(blob){return new Promise((ok,no)=>{const r=new FileReader;r.onload=()=>ok(r.result);r.onerror=no;r.readAsDataURL(blob)})}document.getElementById('voice').onclick=async function(){if(recorder?.state==='recording'){recorder.stop();return}try{stream=await navigator.mediaDevices.getUserMedia({audio:true});chunks=[];recorder=new MediaRecorder(stream);recorder.ondataavailable=e=>chunks.push(e.data);recorder.onstop=async()=>{clearTimeout(timer);stream.getTracks().forEach(x=>x.stop());this.disabled=true;this.textContent='Распознаём…';try{let mime=(recorder.mimeType||'audio/webm').split(';')[0];let audio=await fileData(new Blob(chunks,{type:mime}));let r=await call({action:'transcribe',audio});document.getElementById('text').value=r.text;status.textContent='Проверьте текст перед отправкой.'}catch(e){status.textContent=e.message}finally{this.disabled=false;this.textContent='Записать голосом'}};recorder.start();this.textContent='Остановить запись';timer=setTimeout(()=>{if(recorder.state==='recording')recorder.stop()},90000)}catch(e){status.textContent='Микрофон недоступен. Можно написать сообщение.'}};document.getElementById('feedback').onsubmit=async e=>{e.preventDefault();const b=document.getElementById('send');b.disabled=true;try{const r=await call({text:document.getElementById('text').value,contact:document.getElementById('contact').value,website:document.getElementById('website').value});status.textContent='Спасибо! Обращение №'+r.number+' передано сотрудникам.';document.getElementById('text').value=''}catch(err){status.textContent=err.message}finally{b.disabled=false}};
</script><?php endif;?></main></html>
